import{_ as a,o as t,c as s,ag as r}from"./chunks/framework.DaCm-iTo.js";const g=JSON.parse('{"title":"CoreLib Actions","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/forge/corelib-actions.md","filePath":"en/modules/forge/corelib-actions.md","lastUpdated":null}'),i={name:"en/modules/forge/corelib-actions.md"};function o(n,e,l,d,h,c){return t(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="corelib-actions" tabindex="-1">CoreLib Actions <a class="header-anchor" href="#corelib-actions" aria-label="Permalink to &quot;CoreLib Actions&quot;">​</a></h1><p>When EmakiForge is enabled, it adds forge item refresh stages to the CoreLib action registry. Use them in configured pipelines to rebuild a held forge layer, refresh one player&#39;s inventory, or refresh forged items for all online players after configuration changes.</p><blockquote><p>This page documents only the stages registered by EmakiForge. CoreLib built-in stages are documented in <a href="./../corelib/actions.html">CoreLib Actions</a>. Current stage IDs use only the canonical names below; historical aliases are no longer registered. The old <code>emakiforge_refresh_held</code> is now written <code>forge_refresh_held</code>, and the other two follow the same rule.</p></blockquote><h2 id="stage-ids" tabindex="-1">Stage IDs <a class="header-anchor" href="#stage-ids" aria-label="Permalink to &quot;Stage IDs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Stage ID</th><th>Purpose</th><th>Target requirement</th></tr></thead><tbody><tr><td><code>forge_refresh_held</code></td><td>Refreshes the target player&#39;s main-hand forged item.</td><td><code>REQUIRED_ENTITY</code></td></tr><tr><td><code>forge_refresh_player</code></td><td>Refreshes forged items in the target player&#39;s inventory.</td><td><code>REQUIRED_ENTITY</code></td></tr><tr><td><code>forge_refresh_all</code></td><td>Refreshes forged items for all online players.</td><td><code>NONE</code></td></tr></tbody></table><h2 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h2><p>These stages read no additional parameters.</p><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | forge_refresh_held&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | forge_refresh_player&#39;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # No target needed, so the source can be omitted</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;forge_refresh_all&#39;</span></span></code></pre></div><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li><code>forge_refresh_held</code> only processes the main-hand item. If the player is not holding an item, the stage is skipped.</li><li><code>forge_refresh_player</code> requires a player target and refreshes that player&#39;s inventory through the EmakiForge refresh service.</li><li><code>forge_refresh_all</code> declares <code>NONE</code> as its target requirement, so it can stand alone as a whole pipeline. That makes it suitable for admin pipeline templates or bulk refreshes after configuration changes. It waits for the asynchronous refresh to finish, up to 20 seconds; a timeout, a partial failure, or a configuration generation change during the refresh all end the stage in failure.</li></ul>`,11)])])}const f=a(i,[["render",o]]);export{g as __pageData,f as default};
